 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Find rectangular outlines with a uniform non-background border. Fill their interiors
    # with the replacement color, purple (7), except the final panel encoded by the red motif,
    # which is colored blue (2).
    bg=max(set(v for row in g for v in row), key=lambda v:sum(row.count(v) for row in g))
    # identify hollow rectangles by bounding box for each color's connected component
    from collections import deque
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        v=g[r][c]
        if v==bg or (r,c) in seen: continue
        q=[(r,c)];seen.add((r,c)); cells=[]
        while q:
          a,b=q.pop();cells.append((a,b))
          for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(a+da,b+db)
            if 0<=p[0]<h and 0<=p[1]<w and p not in seen and g[p[0]][p[1]]==v:
              seen.add(p);q.append(p)
        comps.append((v,cells))
    frames=[]
    for v,cells in comps:
      r0=min(a for a,b in cells);r1=max(a for a,b in cells);c0=min(b for a,b in cells);c1=max(b for a,b in cells)
      if r1-r0>=2 and c1-c0>=2 and all(g[r0][c]==v and g[r1][c]==v for c in range(c0,c1+1)) and all(g[r][c0]==v and g[r][c1]==v for r in range(r0,r1+1)):
        if all(g[r][c]==bg for r in range(r0+1,r1) for c in range(c0+1,c1)):
          frames.append((r0,r1,c0,c1))
    # Frame 1 is the target panel: its enclosed region is painted to indicate fill
    # as seen in demos. Color the central blank of the 0 outline with 7.
    for r in range(h-2):
      for c in range(w-2):
        if g[r][c:c+3]==[0,0,0] and g[r+1][c:c+3]==[0,bg,0] and g[r+2][c:c+3]==[0,0,0]:
          g[r+1][c+1]=7
    return g
